from odoo import fields, models


class PurchaseRequisition(models.Model):
    """Purchase agreement ("Contrato de compra") extended for Lotoi."""
    _inherit = 'purchase.requisition'

    # Technical names generated by Odoo Studio, kept so the data is reused.
    requisition_type = fields.Selection(default='purchase_template')
    x_studio_fecha_de_entrega = fields.Date(string='Fecha de Entrega (contrato)')
    x_studio_obra = fields.Char(string='Obra')
    x_studio_selection_field_hc_1j3gn1aa6 = fields.Selection([
        ('TALLER', 'Taller'),
        ('Logistica', 'Logistica'),
        ('Obras', 'Obras'),
        ('Oficina', 'Oficina'),
        ('RRHH', 'RRHH'),
        ('Seg e Hig', 'Seg e Hig'),
    ], string='Sector')
    x_studio_prioridad = fields.Selection([
        ('0', 'Normal'),
        ('1', 'Low'),
        ('2', 'High'),
        ('3', 'Very High'),
    ], string='Prioridad')


class PurchaseRequisitionLine(models.Model):
    _inherit = 'purchase.requisition.line'

    price_unit = fields.Float(default=1.0)
    x_studio_date_field_79k_1j3e8cs07 = fields.Date(string='Fecha de Entrega')
    x_studio_unidades = fields.Selection([
        ('L', 'Lts'),
        ('M', 'Mts'),
        ('mm', 'mm'),
        ('cm', 'Cm'),
        ('kg', 'Kg'),
        ('u', 'Und'),
        ('Bolsas', 'Paq'),
        ('Par', 'Par'),
        ('Jgo', 'Jgo'),
        ('Caja', 'Caja'),
        ('m3', 'm3'),
    ], string='Unidades')
